WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, humidity, firmware, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT CASE WHEN island_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, CASE WHEN humidity >= 75 THEN 'HIGH' ELSE 'LOW' END AS humidity_tier, MAX(reading_ts) AS last_reading_ts, SIZE(COLLECT_SET(device_code)) AS num_device_codes, COUNT(*) FILTER (WHERE device_code = 'DV-04') AS dv_04_rows, COUNT(DISTINCT id) AS distinct_ids, COUNT(CASE WHEN device_code = 'DV-01' THEN 1 END) AS dv_01_count, PERCENT_RANK() OVER (PARTITION BY CASE WHEN island_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY SIZE(COLLECT_SET(device_code)) DESC) AS num_device_codes_percent_rank FROM sessions_device_readings GROUP BY CASE WHEN island_id >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN humidity >= 75 THEN 'HIGH' ELSE 'LOW' END ORDER BY dv_04_rows DESC
